import Phaser from 'phaser';
import { SKINS, skinTexture } from './skins';
import { HERO_BASE_COLORS, HeroColors, WEAPONS, WEAPON_ORDER } from './weapons';

/**
 * Hero sprite sheet (public/assets/hero.png, generated by `npm run sprites`
 * from art/hero.mjs). Loaded once, then recolored into one texture per weapon.
 */
export interface HeroFrameData {
  frameWidth: number;
  frameHeight: number;
  frames: Record<string, number>;
}

export function preloadHero(scene: Phaser.Scene): void {
  scene.load.image('hero_base', 'assets/hero.png');
  scene.load.json('hero_frames', 'assets/hero.json');
}

export function heroFrames(scene: Phaser.Scene): Record<string, number> {
  return (scene.cache.json.get('hero_frames') as HeroFrameData).frames;
}

/** The hero's visor colors in the sheet (main, shade). */
const VISOR = [0x5ef0c8, 0x2aa088];

/** Copy the base hero sheet with exact colors swapped, as a new frame-cut texture. */
function recolorHero(scene: Phaser.Scene, key: string, swap: Map<number, number>): void {
  const meta = scene.cache.json.get('hero_frames') as HeroFrameData;
  const src = scene.textures.get('hero_base').getSourceImage() as HTMLImageElement;
  const canvas = document.createElement('canvas');
  canvas.width = src.width;
  canvas.height = src.height;
  const ctx = canvas.getContext('2d', { willReadFrequently: true })!;
  ctx.drawImage(src, 0, 0);
  const img = ctx.getImageData(0, 0, canvas.width, canvas.height);
  const d = img.data;
  for (let i = 0; i < d.length; i += 4) {
    if (d[i + 3] === 0) continue;
    const to = swap.get((d[i] << 16) | (d[i + 1] << 8) | d[i + 2]);
    if (to === undefined) continue;
    d[i] = (to >> 16) & 255;
    d[i + 1] = (to >> 8) & 255;
    d[i + 2] = to & 255;
  }
  ctx.putImageData(img, 0, 0);
  const tex = scene.textures.addCanvas(key, canvas)!;
  const count = Math.floor(canvas.width / meta.frameWidth);
  for (let i = 0; i < count; i++) tex.add(i, 0, i * meta.frameWidth, 0, meta.frameWidth, meta.frameHeight);
}

/** Blend a color toward white (k > 0) or toward a cool near-black (k < 0). */
function shift(c: number, k: number): number {
  const ch = [(c >> 16) & 255, (c >> 8) & 255, c & 255];
  const to = k > 0 ? [255, 250, 230] : [16, 12, 32];
  const a = Math.abs(k);
  const [r, g, b] = ch.map((v, i) => Math.round(v + (to[i] - v) * a));
  return (r << 16) | (g << 8) | b;
}

/** A weapon's full hero ramp: the extra shades come from its own colors unless given. */
function fullColors(c: HeroColors): Required<HeroColors> {
  return { ...c, shine: c.shine ?? shift(c.light, 0.5), deep: c.deep ?? shift(c.dark, -0.4), suitDark: c.suitDark ?? shift(c.suit, -0.35) };
}

export function createHeroTextures(scene: Phaser.Scene): void {
  const base = fullColors(HERO_BASE_COLORS);
  const keys = Object.keys(base) as (keyof HeroColors)[];
  for (const id of WEAPON_ORDER) {
    const swap = new Map<number, number>();
    const colors = id === 'buster' ? base : fullColors(WEAPONS[id].colors);
    for (const k of keys) swap.set(base[k], colors[k]);
    recolorHero(scene, `hero_${id}`, swap);
  }
  // EX color schemes (classic is the plain Ultra Gun sheet above).
  for (const skin of SKINS) {
    if (!skin.colors) continue;
    const c = fullColors(skin.colors);
    const swap = new Map<number, number>();
    for (const k of keys) swap.set(base[k], c[k]);
    if (skin.visor) {
      swap.set(VISOR[0], skin.visor[0]);
      swap.set(VISOR[1], skin.visor[1]);
    }
    recolorHero(scene, skinTexture(skin.id), swap);
  }
  // Shade, the final boss: a dark UltraGuy with a red visor.
  const shade = fullColors({ light: 0x7a6a9a, main: 0x4a3a6a, dark: 0x2a1a44, suit: 0x140c1c, suitLight: 0x2a2038 });
  const swap = new Map<number, number>();
  for (const k of keys) swap.set(base[k], shade[k]);
  swap.set(VISOR[0], 0xff3050);
  swap.set(VISOR[1], 0xa01830);
  recolorHero(scene, 'hero_shade', swap);
}

/** Steps each run frame shows (8 frames: about two strides a second). */
export const RUN_STEP = 4;
/** Steps the landing squash shows. */
export const LAND_STEPS = 6;

/**
 * Which hero frame to show (UltraGuy and his shadow share the sheet).
 * `runT` counts steps since the run started; `landT` counts down after touching down.
 */
export function heroFrameName(o: { air: boolean; vy: number; running: boolean; runT: number; animT: number; landT: number; shoot: boolean }): string {
  const s = o.shoot ? '_s' : '';
  if (o.air) return `${o.vy < -0.5 ? 'jump' : 'fall'}${s}`;
  // Start a run on the push-off frame, so the first step reads right away.
  if (o.running) return `run${1 + ((Math.floor(o.runT / RUN_STEP) + 1) % 8)}${s}`;
  if (o.landT > 0) return `land${s}`;
  return `idle${1 + (Math.floor(o.animT / 14) % 4)}${s}`;
}
